+fn mod_add_qq_fast_lowscratch(b: &mut B, acc: &[QubitId], a: &[QubitId], p: U256) {
+    let n = acc.len();
+    assert_eq!(n, a.len());
+    debug_assert_eq!(n, 256);
+
+    let (acc_ext, acc_ovf) = ext_reg(b, acc);
+    let (a_ext, a_ovf) = ext_reg(b, a);
+
+    // Step 1: (n+1)-bit operand add (measurement-based Cuccaro, unchanged).
+    add_nbit_qq_fast(b, &a_ext, &acc_ext);
+
+    let c = U256::MAX.wrapping_sub(p).wrapping_add(U256::from(1));
+    // Step 2: unconditional +c via register-free direct const add. A |1> control
+    // makes the controlled primitive unconditional (X/CX/CZ are free Cliffords).
+    let one = b.alloc_qubit();
+    b.x(one);
+    cadd_nbit_const_direct_fast(b, &acc_ext, c, one);
+    b.x(one);
+    b.free(one);
+
+    let flag = b.alloc_qubit();
+    b.cx(acc_ovf, flag);
+    b.x(flag);
+    // Step 3: if flag=0, undo the +c (register-free conditional const sub).
+    csub_nbit_const_direct_fast(b, &acc_ext, c, flag);
+    b.x(flag);
+    b.cx(flag, acc_ovf);
+    cmp_lt_into_fast(b, &acc_ext[..n], &a_ext[..n], flag);
+    b.free(flag);
+
+    unext_reg(b, a_ovf);
+    unext_reg(b, acc_ovf);
+    let _ = (acc_ext, a_ext);
+}

+pub(crate) fn kal_uv_cswap_width(iter_idx: usize, n: usize, invariant: usize) -> usize {
+    if !kal_uv_cswap_trunc_enabled() {
+        return invariant;
+    }
+    let w = kal_wtrunc_width(iter_idx, n).saturating_add(kal_uv_cswap_extra_margin());
+    w.min(invariant)
+}

+pub fn build() -> Vec<Op> {
+    if std::env::var("POINT_ADD_DIALOG_ROUTE").ok().as_deref() != Some("1") {
+        return trailmix_port::build_builder().ops;
+    }

+    circ.set_section("ec3.new_y.dx_diff");
+    mod_neg_inplace_w(circ, &tx[..]); // tx = -new_x
+    mod_double_deferred_w(circ, &tx[..]); // tx = -2*new_x (rfold; mod_mac recanonicalizes)
+    mod_mac_inplace(circ, &tx[..], &lambda, &lambda); // tx += lambda^2 (canonical out)
+    mod_sub_creg_w(circ, &tx[..], ox); // tx -= ox => tx = dx_diff
+    circ.set_section("ec3.new_y.build");
+    mod_mac_inplace(circ, &ty[..], &lambda, &tx[..]); // ty += lambda*dx_diff
+    if !defer_y_materialization_enabled() {
+        mod_sub_creg_w(circ, &ty[..], oy); // ty = new_y
+    }

+/// Per-step register widths (A, B, ca, cb, q). Out-of-range clamps to last.
+#[allow(dead_code)]
+#[must_use]
+pub fn reg_widths(i: usize) -> (usize, usize, usize, usize, usize) {
+    let j = i.min(SHRUNKEN_PZ_NSTEPS - 1);
+    if let Some(thin) = thin_schedule() {
+        let row = thin.widths[j];
+        return (
+            row[0] as usize,
+            row[1] as usize,
+            row[2] as usize,
+            row[3] as usize,
+            row[4] as usize,
+        );
